
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_13_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_13", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.122240950453246e+00, -5.022117031885580e+00, -4.881657129404624e+00, -4.686705339542450e+00, -4.420127482829378e+00, -4.062920382830026e+00, -3.596531356262514e+00, -3.005128347883369e+00, -2.277862701765441e+00, -1.463856755934885e+00, -8.309492226737943e-01, -6.139191258864021e-01, -6.313441581361012e-01, -5.412741868712647e-01, -3.597870396962287e-01, -1.858294023049686e-01, -7.772858772710496e-02, -2.539307260355852e-02, -5.440603996058814e-03, -6.121012250766766e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


